// Addresses saved before this list was completed carry the shorter district names the app used
// to offer — 'Serei Saophoan' where the gazetteer says 'Serei Saophoan Municipality', 'Chamkar
// Mon' where it says 'Chamkar Mon Khan'. Dropping the administrative suffix and matching what is
// left resolves those exactly, so editing an old customer still cascades to their communes rather
// than facing an empty list. Only an exact match after the suffix counts: guessing at a spelling
// would file someone's address under the wrong district, which is worse than not matching.
const ADMIN_SUFFIX = /\s+(municipality|krong|khan|district|srok|city|town)$/i
const districtKey = name => String(name || '').trim().replace(ADMIN_SUFFIX, '').toLowerCase()
const DISTRICT_ALIASES = Object.keys(KH_COMMUNES).reduce((map, official) => {
  const key = districtKey(official)
  // A short form that would match two official districts is left unresolved on purpose.
  map[key] = key in map ? null : official
  return map
}, {})

export function resolveDistrict(district) {
  if (!district) return ''
  if (KH_COMMUNES[district]) return district
  return DISTRICT_ALIASES[districtKey(district)] || district
}

export function getDistricts(province) {
  return (province && KH_DISTRICTS[province]) || []
}

export function getCommunes(district) {
  return (district && KH_COMMUNES[resolveDistrict(district)]) || []
}

// Takes the district as well as the commune — see the note above on repeated commune names.
export function getVillages(district, commune) {
  if (!district || !commune) return []
  return KH_VILLAGES[resolveDistrict(district) + '|' + commune] || []
}
